// n8n SSH 노드(typeVersion 1)는 종료코드를 무시하고 항상 success 를 낸다.
// 헬퍼가 죽어도 Error Workflow 가 안 뜨므로 여기서 모아 던진다.
// 전용 노드로 표현 불가능해 Code 를 쓴다.
// 이 파이프라인은 run.json 단락 규약이 있다 — 상류가 죽으면 하류는 {skipped:true} 로
// exit 0 을 내므로, 실패는 정확히 **한 노드**에서만 exit≠0 으로 나타난다.
const expect = {
  '1. export 수신': 'fetch-export',
  '2. 적재': 'ingest',
  '3. 결정 태깅': 'tag',
  '4a. 쿠팡 매칭': 'match-coupang',
  '4b. 컬리 매칭': 'match-kurly',
  '4c. 네이버페이 매칭': 'match-naver',
  '5. apply': 'apply',
  '6. LLM 용도추론': 'llm',
  '6c. LLM 경보': 'notify',
  '7. 산출물 생성·전달': 'export',
  '8. 결과 알림·락 해제': 'finish',
};
const failed = [], checked = [], skipped = [], detail = [];
for (const name of Object.keys(expect)) {
  let items;
  try { items = $(name).all(); } catch (e) { skipped.push(name + ' (미실행)'); continue; }
  if (!items || !items.length) { skipped.push(name + ' (출력 없음)'); continue; }
  const j = items[0].json;
  if (j.code === undefined) { skipped.push(name + ' (SSH 출력 아님)'); continue; }
  if (j.code !== 0) {
    const tail = String(j.stderr || '').trim().split('\n').pop() || '(stderr 없음)';
    detail.push(name + ' exit ' + j.code + ': ' + tail.slice(0, 200));
    failed.push(name + '(exit ' + j.code + ')');
    continue;
  }
  let own = null;
  try { own = JSON.parse(String(j.stdout || '')).node; } catch (e) { /* 파싱 불가 */ }
  if (own !== expect[name]) { skipped.push(name + ' (disabled — 통과만 함)'); continue; }
  checked.push(name);
}
if (failed.length) {
  console.log('실패 상세: ' + detail.join(' | '));
  throw new Error('가계 파이프라인 노드 실패: ' + failed.join(', '));
}
return [{ json: { all_ok: true, checked, skipped } }];
